// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY, LogFile} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(address actor, uint256 amount, address bogus) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e30);
        LogFile log = new LogFile();
        // set the real log file through SetLogFile, then init
        c.SetLogFile(address(log));
        c.Initialized();
        // now any further SetLogFile call reverts in both versions; observe via Put instead:
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(0) { ok = true; } catch { ok = false; }
        // Rule: once a LogFile has been registered via SetLogFile, deposits (Put)
        // succeed because events are logged to that file for every admissible input.
        assertTrue(ok);
    }
}
